interface JwtPayload { sub: string; jti: string; typ: 'access' | 'refresh'; iat: number; exp: number; }

function b64url(buf: Buffer): string { return buf.toString('base64url'); }

function signJwt(payload, secret): string {
  const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const body = b64url(Buffer.from(JSON.stringify(payload)));
  const sig = crypto.createHmac('sha256', secret).update(`${header}.${body}`).digest('base64url');
  // store sig as base64url string; verify by recomputing and timingSafeEqual on buffers
  return `${header}.${body}.${sig}`;
}

