function verifyJwt(token: string, secret: string, expectedType): JwtPayload | null {
  const parts = token.split('.');
  if (parts.length !== 3) return null;
  const [h, b, s] = parts;
  // validate header
  let header; try { header = JSON.parse(Buffer.from(h, 'base64url').toString('utf8')); } catch { return null; }
  if (header?.alg !== 'HS256' || header?.typ !== 'JWT') return null; // prevents alg confusion
  const expected = crypto.createHmac('sha256', secret).update(`${h}.${b}`).digest();
  const given = Buffer.from(s, 'base64url'); // hmm, base64url decode of arbitrary string
  if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) return null;
  let payload; try { payload = JSON.parse(Buffer.from(b, 'base64url').toString('utf8')); } catch { return null; }
  const now = Math.floor(Date.now() / 1000);
  if (typeof payload.exp !== 'number' || payload.exp <= now) return null;
  if (payload.typ !== expectedType) return null;
  if (typeof payload.sub !== 'string' || typeof payload.jti !== 'string') return null;
  return payload;
}

