async function checkRateLimit(store, key, limit, windowMs): Promise<{ allowed: boolean; retryAfterSec: number; remaining: number }> {
  const { count, resetAt } = await store.incr(key, windowMs);
  if (count > limit) return { allowed: false, retryAfterSec: Math.max(1, Math.ceil((resetAt - Date.now())/1000)), remaining: 0 };
  return { allowed: true, retryAfterSec: 0, remaining: limit - count };
}
